cd /work/output/artifacts/skill-flow-group-to-subflow/BellevueWeather/BellevueWeather && python3 - <<'PY'
import json, uuid

FLOW_FILE = "BellevueWeather.flow"

with open(FLOW_FILE) as f:
    flow = json.load(f)

# ── 1. Extract the two nodes being moved into the subflow ──────────────────────
def pop_node(nid):
    idx = next(i for i, n in enumerate(flow['nodes']) if n['id'] == nid)
    return flow['nodes'].pop(idx)

getWeather_node    = pop_node('getWeather')
formatSummary_node = pop_node('formatSummary')

# ── 2. Remove the three edges that connected them in the main flow ─────────────
remove_edge_ids = {
    'edge-start-getWeather',
    'edge-getWeather-formatSummary',
    'edge-formatSummary-checkTemperature',
}
flow['edges'] = [e for e in flow['edges'] if e['id'] not in remove_edge_ids]

# ── 3. Build the fetchAndFormat subflow node (parent) ─────────────────────────
subflow_node = {
    "id": "fetchAndFormat",
    "type": "core.subflow",
    "typeVersion": "1.0",
    "display": {"label": "fetchAndFormat"},
    "inputs": {},
    "outputs": {
        "output": {
            "type": "object",
            "description": "The return value of the subflow",
            "source": "=result.response",
            "var": "output"
        },
        "error": {
            "type": "object",
            "description": "Error information if the subflow fails",
            "source": "=result.Error",
            "var": "error"
        }
    }
}

# Insert after 'start'
start_idx = next(i for i, n in enumerate(flow['nodes']) if n['id'] == 'start')
flow['nodes'].insert(start_idx + 1, subflow_node)

# ── 4. Add new main-flow edges ─────────────────────────────────────────────────
flow['edges'] = [
    {
        "id": "edge-start-fetchAndFormat",
        "sourceNodeId": "start",
        "sourcePort": "output",
        "targetNodeId": "fetchAndFormat",
        "targetPort": "input"
    },
    {
        "id": "edge-fetchAndFormat-checkTemperature",
        "sourceNodeId": "fetchAndFormat",
        "sourcePort": "output",
        "targetNodeId": "checkTemperature",
        "targetPort": "input"
    }
] + flow['edges']

# ── 5. Update expressions in main flow to read from fetchAndFormat output ──────
for n in flow['nodes']:
    if n['id'] == 'checkTemperature':
        n['inputs']['expression'] = '$vars.fetchAndFormat.output.temperatureF > 60'
    if n['id'] == 'endNiceDay':
        n['outputs']['summary']['source']['expression'] = \
            "({ message: 'nice day', temperatureF: $vars.fetchAndFormat.output.temperatureF, description: $vars.fetchAndFormat.output.summary })"
    if n['id'] == 'endBringJacket':
        n['outputs']['summary']['source']['expression'] = \
            "({ message: 'bring a jacket', temperatureF: $vars.fetchAndFormat.output.temperatureF, description: $vars.fetchAndFormat.output.summary })"

# ── 6. Add core.subflow definition ────────────────────────────────────────────
core_subflow_def = {
    "nodeType": "core.subflow",
    "version": "1.0",
    "category": "control-flow",
    "description": "Group steps into a reusable subflow",
    "tags": ["subflow", "composite", "container", "subprocess"],
    "sortOrder": 20,
    "supportsErrorHandling": True,
    "display": {"label": "Subflow", "icon": "layers"},
    "handleConfiguration": [
        {
            "position": "left",
            "handles": [{"id": "input", "type": "target", "handleType": "input"}],
            "visible": True
        },
        {
            "position": "right",
            "handles": [
                {"id": "output", "type": "source", "handleType": "output"},
                {
                    "id": "error",
                    "label": "Error",
                    "type": "source",
                    "handleType": "output",
                    "visible": "{inputs.errorHandlingEnabled}",
                    "constraints": {"maxConnections": 1}
                }
            ],
            "visible": True
        }
    ],
    "model": {"type": "bpmn:SubProcess"},
    "outputDefinition": {
        "error": {
            "type": "object",
            "description": "Error information if the node fails",
            "source": "=Error",
            "var": "error",
            "schema": {
                "$schema": "http://json-schema.org/draft-07/schema#",
                "type": "object",
                "required": ["code", "message", "detail", "category", "status"],
                "properties": {
                    "code":     {"type": "string",  "description": "Error code as a string"},
                    "message":  {"type": "string",  "description": "High-level error message"},
                    "detail":   {"type": "string",  "description": "Detailed error description"},
                    "category": {"type": "string",  "description": "Error category"},
                    "status":   {"type": "integer", "description": "HTTP status code"}
                },
                "additionalProperties": False
            }
        }
    },
    "drillable": True,
    "runtimeConstraints": {"exclude": ["api-function"]}
}
flow['definitions'].append(core_subflow_def)

# ── 7. Update main-flow variables.nodes ───────────────────────────────────────
moved_var_ids = {'getWeather.output', 'getWeather.error', 'formatSummary.output', 'formatSummary.error'}
flow['variables']['nodes'] = [
    v for v in flow['variables']['nodes'] if v['id'] not in moved_var_ids
]
flow['variables']['nodes'].append({
    "id": "fetchAndFormat.output",
    "type": "object",
    "description": "Output from the fetchAndFormat subflow",
    "binding": {"nodeId": "fetchAndFormat", "outputId": "output"}
})

# ── 8. Build the subflow content ──────────────────────────────────────────────
sf_start_id  = "fetchAndFormatStart"
sf_end_id    = "fetchAndFormatEnd"
sf_entry_uuid = str(uuid.uuid4())

sf_start = {
    "id": sf_start_id,
    "type": "core.trigger.manual",
    "typeVersion": "1.0",
    "display": {"label": "Start"},
    "inputs": {
        "entryPointId": sf_entry_uuid,
        "isDefaultEntryPoint": True
    },
    "outputs": {
        "output": {
            "type": "object",
            "description": "Data passed when manually triggering the workflow.",
            "source": "null",
            "var": "output"
        }
    }
}

sf_end = {
    "id": sf_end_id,
    "type": "core.control.end",
    "typeVersion": "1.0",
    "display": {"label": "End"},
    "inputs": {},
    "outputs": {
        "temperatureF": {"source": "=js:$vars.formatSummary.output.temperatureF"},
        "summary":      {"source": "=js:$vars.formatSummary.output.summary"}
    }
}

flow['subflows'] = {
    "fetchAndFormat": {
        "nodes": [sf_start, getWeather_node, formatSummary_node, sf_end],
        "edges": [
            {
                "id": "sf-edge-start-getWeather",
                "sourceNodeId": sf_start_id,
                "sourcePort": "output",
                "targetNodeId": "getWeather",
                "targetPort": "input"
            },
            {
                "id": "sf-edge-getWeather-formatSummary",
                "sourceNodeId": "getWeather",
                "sourcePort": "default",
                "targetNodeId": "formatSummary",
                "targetPort": "input"
            },
            {
                "id": "sf-edge-formatSummary-end",
                "sourceNodeId": "formatSummary",
                "sourcePort": "success",
                "targetNodeId": sf_end_id,
                "targetPort": "input"
            }
        ],
        "variables": {
            "globals": [
                {"id": "temperatureF", "direction": "out", "type": "number"},
                {"id": "summary",      "direction": "out", "type": "string"}
            ],
            "nodes": [
                {
                    "id": "getWeather.output",
                    "type": "object",
                    "description": "HTTP response from open-meteo API",
                    "binding": {"nodeId": "getWeather", "outputId": "output"}
                },
                {
                    "id": "getWeather.error",
                    "type": "object",
                    "description": "Error if weather fetch fails",
                    "binding": {"nodeId": "getWeather", "outputId": "error"}
                },
                {
                    "id": "formatSummary.output",
                    "type": "object",
                    "description": "Formatted weather summary with temperature and description",
                    "binding": {"nodeId": "formatSummary", "outputId": "output"}
                },
                {
                    "id": "formatSummary.error",
                    "type": "object",
                    "description": "Error if formatting script fails",
                    "binding": {"nodeId": "formatSummary", "outputId": "error"}
                }
            ]
        },
        "layout": {
            "nodes": {
                sf_start_id:    {"position": {"x": 200, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
                "getWeather":   {"position": {"x": 450, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
                "formatSummary":{"position": {"x": 700, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
                sf_end_id:      {"position": {"x": 950, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False}
            }
        }
    }
}

# ── 9. Update top-level layout ────────────────────────────────────────────────
for nid in ('getWeather', 'formatSummary'):
    flow['layout']['nodes'].pop(nid, None)
flow['layout']['nodes']['fetchAndFormat'] = {
    "position": {"x": 450, "y": 144},
    "size": {"width": 96, "height": 96},
    "collapsed": False
}

# ── 10. Write back ─────────────────────────────────────────────────────────────
with open(FLOW_FILE, 'w') as f:
    json.dump(flow, f, indent=2)

print("Done — flow rewritten.")
PY

